      SUBROUTINE FNDLAB(KNAME,NELMN)CC---- LOCATE NAMED ELEMENTCC-----------------------------------------------------------------------      CHARACTER*15    KNAME      INTEGER         NELMNC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'C-----------------------------------------------------------------------      INTEGER         NUMM, TYPECC      NELMN = 0      IF (NEL .EQ. 0) GO TO 200      DO 20 NUM = 1, NEL      NUMM = NUM      II = ISTOR(NUM)      TYPEC = IDATA(II)      IF (TYPEC .NE. 55) THEN        IF (KNAME .EQ. LABEL(NUM)) GO TO 100      ENDIF   20 CONTINUE      GO TO 200C  100 NELMN = NUMM  200 CONTINUE      RETURN      END